var K = window.__K || (window.__K = {});
K.P = 'br';
K.NODES = ["apps","vault","cloud","thief"];
K.WIRES = ["direct","a1","a2","steal"];
K.CUTS = ["steal"];

K.sel = function(kind, id){ return '#' + K.P + '-' + kind + '-' + id; };

/* Pills. value null leaves the number alone. */
K.pill = function(i, value, unit, tone){
  if(value !== null) MSD.q('#' + K.P + '-pill-v-' + i).textContent = value;
  if(unit !== null && unit !== undefined) MSD.q('#' + K.P + '-pill-u-' + i).textContent = unit;
  MSD.cls('#' + K.P + '-pill-' + i, 'bad', tone === 'bad');
  MSD.cls('#' + K.P + '-pill-' + i, 'good', tone === 'good');
};
K.pillLabel = function(i, text){ MSD.q('#' + K.P + '-pill-l-' + i).textContent = text; };

/* Which nodes are in the picture, and which this stage is about. */
K.nodes = function(list, live){
  K.NODES.forEach(function(n){
    MSD.cls(K.sel('n', n), 'on', list.indexOf(n) !== -1);
    MSD.cls(K.sel('n', n), 'live', (live || []).indexOf(n) !== -1);
  });
};

K.label = function(id, text){ MSD.q(K.sel('l', id)).textContent = text; };

/* Wires. map is { id: [state, tone] }; anything omitted is turned off.
   state: off | on | flow | dead.  tone: '' | hot | bad | ok. */
K.wires = function(map){
  K.WIRES.forEach(function(id){
    var v = (map || {})[id] || ['off', ''];
    var el = K.sel('w', id);
    MSD.cls(el, 'on',   v[0] !== 'off');
    MSD.cls(el, 'flow', v[0] === 'flow');
    MSD.cls(el, 'dead', v[0] === 'dead');
    MSD.cls(el, 'hot',  v[1] === 'hot');
    MSD.cls(el, 'bad',  v[1] === 'bad');
    MSD.cls(el, 'ok',   v[1] === 'ok');
  });
};

/* Counter beside a node. null hides it. It renders under the node's label. */
K.cnt = function(id, value, flip){
  var el = K.sel('c', id);
  MSD.cls(el, 'on', value !== null);
  MSD.cls(el, 'flip', flip === true);
  if(value !== null) MSD.q(el).textContent = value;
};
K.clearCnt = function(){ K.NODES.forEach(function(n){ K.cnt(n, null); }); };

K.cut = function(list){
  K.CUTS.forEach(function(id){ MSD.cls(K.sel('x', id), 'on', (list || []).indexOf(id) !== -1); });
};

/* Code block. lines is an array of HTML strings; active/hit are 1-based. */
K.code = function(file, lines, opts){
  opts = opts || {};
  MSD.q('#' + K.P + '-code-h').textContent = file;
  for(var i = 1; i <= 5; i++){
    MSD.q('#' + K.P + '-ln-' + i).innerHTML = lines[i - 1] || '';
    MSD.cls('#' + K.P + '-ln-' + i, 'active', i === opts.active);
    MSD.cls('#' + K.P + '-ln-' + i, 'hit', i === opts.hit);
    MSD.cls('#' + K.P + '-ln-' + i, 'gone', (opts.gone || []).indexOf(i) !== -1);
  }
  MSD.cls('#' + K.P + '-code', 'bad', opts.tone === 'bad');
  MSD.cls('#' + K.P + '-code', 'good', opts.tone === 'good');
};

/* Payoff. Call with no args on every non-final stage to keep it hidden. */
K.payoff = function(on){
  MSD.cls('#' + K.P + '-map', 'dim', on === true);
  MSD.cls('#' + K.P + '-payoff', 'on', on === true);
};

/* Reset everything a stage might have left behind. Call first, always. */
K.reset = function(){
  K.payoff(false);
  K.cut([]);
  K.clearCnt();
};

K.SHIPPED = [
  '<span class="c">// shipped to 40,000 phones</span>',
  '<span class="k">var</span> key = <span class="s">"sk-live-7f3a91c4"</span>;',
  '',
  '<span class="c">// rotating this breaks every install</span>',
  ''
];
K.VAULTED = [
  'builder.Configuration.<span class="f">AddAzureKeyVault</span>(',
