  '',
  '<span class="c">// az keyvault secret set --name OpenAiKey</span>',
  '<span class="g">// rotated. no build. no store. no wait.</span>'
];

K.reset();
K.pill(1, '$0', '', '');
K.pill(2, '0', 'days', '');
K.nodes(['apps', 'cloud'], ['apps']);
K.wires({ direct: ['flow', ''] });
K.cnt('apps', '40,000');
K.cnt('cloud', '$0');
K.code('MauiProgram.cs · ships with the app', K.SHIPPED, { active: 2 });

